x;\n  transition: all 0.3s ease;\n  position: relative;\n  overflow: hidden;\n  border: 1.2px solid #eee;\n  display: flex;\n  flex-direction: column;\n}\n\n.wuwa-panel__scroll {\n  position: relative;\n  z-index: 5;\n  flex: 1;\n  min-height: 0;\n  overflow-x: hidden;\n  overflow-y: auto;\n  padding: 48px 20px 16px;\n  box-sizing: border-box;\n  scrollbar-width: thin;\n  scrollbar-color: rgba(56, 189, 248, 0.45) transparent;\n}\n\n.wuwa-panel__scroll::-webkit-scrollbar {\n  width: 5px;\n}\n\n.wuwa-panel__scroll::-webkit-scrollbar-thumb {\n  background: rgba(56, 189, 248, 0.45);\n  border-radius: 999px;\n}\n\n.wuwa-logo-container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  width: 100%;\n  margin-bottom: 16px;\n  position: relative;\n  z-index: 10;\n  padding-top: 8px;\n}\n\n.wuwa-logo {\n  max-width: 180px;\n  height: auto;\n  filter: drop-shadow(0 0 12px rgba(56, 189, 248, 0.5));\n  will-change: transform, opacity;\n}\n\n.wuwa-logo-container--intro {\n  animation: logoIntro 1.2s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n}\n\n@keyframes logoIntro {\n  0% {\n    transform: scale(1.4) translateY(150px);\n    opacity: 0;\n  }\n  40% {\n    opacity: 1;\n  }\n  100% {\n    transform: scale(1) translateY(0);\n    opacity: 1;\n  }\n}\n\n@keyframes fadeInUp {\n  from {\n    opacity: 0;\n    transform: translateY(20px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@keyframes heartbeat {\n  0% {\n    transform: scale(1);\n    box-shadow: 0 4px 15px rgba(2, 132, 199, 0.3);\n  }\n  50% {\n    transform: scale(1.03);\n    box-shadow: 0 0 25px rgba(56, 189, 248, 0.6);\n  }\n  100% {\n    transform: scale(1);\n    box-shadow: 0 4px 15px rgba(2, 132, 199, 0.3);\n  }\n}\n\n.wuwa-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 16px;\n  opacity: 0;\n  position: relative;\n  z-index: 5;\n}\n\n.wuwa-grid--intro {\n  animation: fadeInUp 0.8s ease 0.6s forwards;\n}\n\n@media (min-width: 520px) {\n  .wuwa-grid {\n    grid-template-columns: 1fr 1fr;\n    align-items: start;\n  }\n}\n\n.wuwa-label {\n  display: block;\n  font-size: 0.9em;\n  color: #0284c7;\n  margin-bottom: 8px;\n  font-weight: 600;\n  margin-top: 16px;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.wuwa-label--required {\n  color: #fbbf24;\n}\n\n.wuwa-input,\n.wuwa-select,\n.wuwa-textarea {\n  width: 100%;\n  background: #f8fafc;\n  border: 1px solid #cbd5e1;\n  color: #1e293b;\n  padding: 12px;\n  border-radius: 8px;\n  outline: none;\n  font-size: 0.95em;\n  box-sizing: border-box;\n  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n.wuwa-textarea {\n  resize: vertical;\n  min-height: 80px;\n  line-height: 1.5;\n}\n\n.wuwa-input:focus,\n.wuwa-select:focus,\n.wuwa-textarea:focus {\n  border-color: #38bdf8;\n  background: #ffffff;\n  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15);\n}\n\n.wuwa-input--error {\n  border-color: #fc8181 !important;\n}\n\n.toggle-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin-bottom: 12px;\n  cursor: pointer;\n  background: #e2e8f0;\n  padding: 12px;\n  border-radius: 10px;\n  border: 1.5px solid #cbd5e1;\n  transition: all 0.2s ease;\n}\n\n.toggle-row:hover {\n  background: #e0f2fe;\n  border-color: rgba(56, 189, 248, 0.4);\n}\n\n.toggle-row--plain {\n  background: transparent;\n  padding: 0;\n  border: none;\n  margin: 0;\n}\n\n.toggle-row input[type='checkbox'] {\n  width: 20px;\n  height: 20px;\n  accent-color: #0ea5e9;\n  cursor: pointer;\n}\n\n.toggle-row--refine {\n  margin-top: 10px;\n  background: rgba(56, 189, 248, 0.1);\n  border-color: rgba(56, 189, 248, 0.3);\n}\n\n.toggle-text {\n  color: #1e293b;\n  font-weight: 600;\n  font-size: 1.05em;\n}\n\n.toggle-text--small {\n  font-size: 0.95em;\n}\n\n.anim-box {\n  overflow: hidden;\n  transition:\n    max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1),\n    opacity 0.4s ease;\n  max-height: 0;\n  opacity: 0;\n}\n\n.anim-box.open {\n  max-height: 1000px;\n  opacity: 1;\n}\n\n.warning