import { stripWuwaBoilerplate } from './wuwaMessageSanitize';
import { getMvuApi } from './wuwaTavern';

/**
 * 伪同层存档层：用聊天变量（{type:'chat'}）持久化剧情历史与 MVU 变量快照，
 * 使游玩数据不再依赖酒馆聊天楼层，剧情消息不再出现在酒馆聊天记录里。
 *
 * 存储键：chat 变量下的 `wuwa_archive`（只更新该键，不覆盖聊天变量的其他字段）。
 */

export type WuwaTurnRole = 'user' | 'assistant';

export type WuwaTurn = {
  /** 自增 id（从 1 开始），替代 message_id 用于定位回合 */
  id: number;
  role: WuwaTurnRole;
  /** 原始消息正文（含 <gal>/<status>/<UpdateVariable> 等标签） */
  text: string;
  /** 仅 user 轮：玩家原始输入（不含 <status> 引导词），用于前端展示与编辑回溯 */
  user_input?: string;
  /** 仅 assistant 轮：该轮解析后的 stat_data 快照，用于编辑/重新生成时回溯基线 */
  stat_after?: Record<string, unknown>;
};

export type WuwaArchive = {
  /** 最新 MVU 变量快照（stat_data） */
  stat_data: Record<string, unknown>;
  /** 初始 stat_data（init 完成后、首次生成前），编辑首轮时作为回溯基线 */
  init_stat: Record<string, unknown>;
  /** 剧情历史（上下文注入 + 前端书页重建的唯一数据源） */
  turns: WuwaTurn[];
  /** 初始文本（开场引导词），供前端「初始文本」面板展示 */
  init_text: string;
  /** 记忆总结（定期由 LLM 生成，注入后续上下文） */
  summary: string;
  next_id: number;
  game_started: boolean;
};

const ARCHIVE_KEY = 'wuwa_archive';

export function defaultArchive(): WuwaArchive {
  return {
    stat_data: {},
    init_stat: {},
    turns: [],
    init_text: '',
    summary: '',
    next_id: 1,
    game_started: false,
  };
}

function normalizeArchive(raw: unknown): WuwaArchive {
  const base = defaultArchive();
  if (!raw || typeof raw !== 'object') return base;
  const obj = raw as Partial<WuwaArchive>;
  return {
    ...base,
    ...obj,
    stat_data: obj.stat_data && typeof obj.stat_data === 'object' ? obj.stat_data : {},
    init_stat: obj.init_stat && typeof obj.init_stat === 'object' ? obj.init_stat : {},
    turns: Array.isArray(obj.turns) ? (obj.turns as WuwaTurn[]) : [],
    init_text: typeof obj.init_text === 'string' ? obj.init_text : '',
    summary: typeof obj.summary === 'string' ? obj.summary : '',
    next_id: typeof obj.next_id === 'number' ? obj.next_id : 1,
    game_started: Boolean(obj.game_started),
  };
}

function readChatVariables(): Record<string, any> {
  try {
    return getVariables({ type: 'chat' }) ?? {};
  } catch {
    return {};
  }
}

export function readArchive(): WuwaArchive {
  return normalizeArchive(readChatVariables()[ARCHIVE_KEY]);
}

export function writeArchive(archive: WuwaArchive): void {
  try {
    updateVariablesWith((variables) => {
      variables[ARCHIVE_KEY] = archive;
      return variables;
    }, { type: 'chat' });
  } catch (error) {
    console.warn('[鸣潮 archive] 写入聊天变量失败', error);
  }
}

/** 函数式更新存档；updater 返回新 archive 后原子写回 */
export function updateArchive(updater: (archive: WuwaArchive) => WuwaArchive): WuwaArchive {
  const next = updater(readArchive());
  writeArchive(next);
  return next;
}

/** 清空存档（切换聊天后由 CHAT_CHANGED 触发） */
export function resetArchive(): void {
  writeArchive(defaultArchive());
}

/**
 * 重置整局游戏：清空剧情存档（turns/stat_data/init_stat/summary/game_started），
 * 并把 0 楼 MVU 变量（stat_data）清空，使界面回到开局（game_started=false）。
 */
export async function resetWuwaGame(): Promise<void> {
  resetArchive();
  await syncArchiveStatToFloorZero({});
}

/** 最新一条 assistant 轮 */
export function latestAssistantTurn(archive: WuwaArchive): WuwaTurn | null {
  for (let i = archive.turns.length - 1; i >= 0; i -= 1) {
    if (archive.turns[i].role === 'assistant') return archive.turns[i];
  }
  return null;
}

/** 回溯 turn_index 之前的最近一次 assistant 快照；没有则回退到 init_stat */
export function baselineStatBefore(archive: WuwaArchive, turn_index: number): Record<string, unknown> {
  for (let i = turn_index - 1; i >= 0; i -= 1) {
    const turn = archive.turns[i];
    if (turn.role === 'assistant' && turn.stat_after) return turn.stat_after;
  }
  return { ...archive.init_stat };
}

/** 生成上下文用的历史提示词（RolePrompt[]），按时间顺序；summary 固定置顶，turns 仅取最近 limit 条 */
export function archiveContextPrompts(
  archive: WuwaArchive,
  limit = 40,
): Array<{ role: 'system' | 'assistant' | 'user'; content: string }> {
  const prompts: Array<{ role: 'system' | 'assistant' | 'user'; content: string }> = [];
  if (archive.summary.trim()) {
    prompts.push({ role: 'system', content: `【剧情记忆总结】\n${archive.summary.trim()}` });
  }
  const recent = limit > 0 ? archive.turns.slice(-limit) : archive.turns;
  for (const turn of recent) {
    if (turn.role === 'user') prompts.push({ role: 'user', content: turn.text });
    else prompts.push({ role: 'assistant', content: turn.text });
  }
  return prompts;
}

/** 判断文本是否含 <gal> 剧情块（剥离思维链/尾部元数据后） */
export function hasGalInText(message: string): boolean {
  return /<gal>[\s\S]*?<\/gal>/i.test(stripWuwaBoilerplate(message));
}

/** 存档中是否已进入可游玩阶段（有真实 <gal> 剧情） */
export function archiveGameStarted(archive: WuwaArchive): boolean {
  if (archive.game_started) return true;
  return archive.turns.some((turn) => turn.role === 'assistant' && hasGalInText(turn.text));
}

/** 最新一条含 <gal> 的 assistant 轮 */
export function latestGalTurn(archive: WuwaArchive): WuwaTurn | null {
  for (let i = archive.turns.length - 1; i >= 0; i -= 1) {
    const turn = archive.turns[i];
    if (turn.role === 'assistant' && hasGalInText(turn.text)) return turn;
  }
  return null;
}

/**
 * 将最新 stat_data 同步到 0 楼（问候楼层）的 MVU 数据，
 * 供浪潮/手机状态栏等楼层读取方继续使用；不创建新消息楼层。
 */
export async function syncArchiveStatToFloorZero(stat_data: Record<string, unknown>): Promise<void> {
  try {
    const MvuApi = getMvuApi();
    const current =
      MvuApi.getMvuData({ type: 'message', message_id: 0 }) ?? { stat_data: {}, initialized_lorebooks: {} };
    await MvuApi.replaceMvuData({ ...current, stat_data }, { type: 'message', message_id: 0 });
  } catch (error) {
    console.warn('[鸣潮 archive] 同步 stat_data 到 0 楼失败', error);
  }
}