import { archiveGameStarted, latestGalTurn, readArchive } from '../../shared/wuwaArchive';
import { OPENING_MARKER } from '../开场/constants';
import { HUB_FLOOR_ID } from './constants';
import { hasGalBlock } from './wuwaParser';
/** 存档中是否已进入可游玩阶段（有真实 <gal> 剧情），不再依赖聊天楼层 */
export function chatHasWuwaGameStarted() {
    return archiveGameStarted(readArchive());
}
/** 最新含 <gal> 的 assistant 轮（来自存档，message_id 即回合 id） */
export function getLatestWuwaMessage() {
    const turn = latestGalTurn(readArchive());
    if (!turn)
        return null;
    return { message_id: turn.id, message: turn.text };
}
/** 伪同层 iframe 固定挂第 0 楼（问候楼层） */
export function resolveHubMountFloorId() {
    return HUB_FLOOR_ID;
}
/** 剧情正文由 gameStore 从存档读取；挂载仅要求第 0 楼含开场标记或已开局 */
export function shouldMountHub(message_id, message) {
    if (message_id !== HUB_FLOOR_ID)
        return false;
    if (chatHasWuwaGameStarted())
        return true;
    if (hasGalBlock(message))
        return true;
    return message.includes(OPENING_MARKER);
}
/** @deprecated 使用 shouldMountHub */
export function isHubFloor(message_id) {
    return message_id === HUB_FLOOR_ID;
}
/** 响应式作用域：全部来自存档，不再注入/读取楼层流式上下文 */
export function useMessageScope() {
    const message_id = computed(() => latestGalTurn(readArchive())?.id ?? 0);
    const message_text = computed(() => latestGalTurn(readArchive())?.text ?? '');
    const is_streaming = computed(() => false);
    const streaming = inject('streaming_message_context', null);
    return { streaming, message_id, message_text, is_streaming };
}
