import { readArchive } from './wuwaArchive';
import { stripWuwaBoilerplate } from './wuwaMessageSanitize';

/**
 * 手机「信息」聊天的独立存档层：用聊天变量（{type:'chat'}）持久化手机私聊/群聊消息，
 * 使手机信息功能不再写入酒馆聊天楼层（不产生楼层消息、不在酒馆显示、不进聊天记录）。
 *
 * 存储键：chat 变量下的 `wuwa_phone_chat`（只更新该键，不覆盖聊天变量的其他字段）。
 * 消息体结构与旧版读取的 tavern chat 消息保持一致（mes/is_user/send_date），
 * 便于复用 legacyPhone 现有的正则解析逻辑。
 */

export type PhoneChatMessage = {
  /** 消息正文（含 [我方消息|…]、[对方消息|…]、[群聊消息|…]、[群聊|…] 等标记） */
  mes: string;
  is_user: boolean;
  name?: string;
  send_date?: number;
};

export type PhoneGeneratePrompt = { role: 'system' | 'assistant' | 'user'; content: string };

const STORE_KEY = 'wuwa_phone_chat';

function readRawStore(): PhoneChatMessage[] {
  try {
    const variables = getVariables({ type: 'chat' }) ?? {};
    const raw = variables[STORE_KEY];
    if (!Array.isArray(raw)) return [];
    return raw.filter((m) => m && typeof m.mes === 'string');
  } catch {
    return [];
  }
}

function writeRawStore(messages: PhoneChatMessage[]): void {
  try {
    updateVariablesWith((variables) => {
      variables[STORE_KEY] = messages;
      return variables;
    }, { type: 'chat' });
  } catch (error) {
    console.warn('[鸣潮手机] 写入手机聊天存档失败', error);
  }
}

export function readPhoneChat(): PhoneChatMessage[] {
  return readRawStore();
}

export function appendPhoneChat(messages: PhoneChatMessage[]): PhoneChatMessage[] {
  const next = [...readRawStore(), ...messages];
  writeRawStore(next);
  return next;
}

export function replacePhoneChat(messages: PhoneChatMessage[]): PhoneChatMessage[] {
  writeRawStore(messages);
  return messages;
}

export function clearPhoneChat(): void {
  writeRawStore([]);
}

/**
 * 手机飞讯生成隔离护栏：与剧情扮演彻底解耦。
 * 禁止输出任何剧情标签、思维链、图片标签，唯一合法输出是纯文本手机短信格式。
 */
const PHONE_SYSTEM_GUARD = `【手机飞讯生成元任务·最高优先级】
你正在执行手机飞讯聊天生成，不是主线剧情扮演。你要模拟的是一条真实手机短信/飞讯消息，只输出消息本身，不要任何附加内容。
严禁输出：<gal>、<z>、<other>、<options>、<UpdateVariable>、<StatusPlaceHolderImpl>、<current_event>、<progress>、<konatan_chat>、<konatan_planning~>、<pic>、<心> 等任何剧情/图片标签。
严禁输出任何形式的思考过程、自我核对、剧情设计、推理、推演、ooc 检查等旁白（例如「剧情设计:…梳理完毕」）。
严禁续写、扩写或复述当前剧情场景的旁白描写；你只能回复聊天消息本身，像真人发短信一样简短自然。
唯一合法输出：私聊使用 [对方消息|角色名字|号码|消息类型|消息内容]，群聊使用 [群聊消息|群号|发送者名字|消息类型|消息内容] 逐行回复，每条消息单独成行，可回复多条。
消息内容必须是纯文本，禁止出现任何尖括号标签。`;

/**
 * 将剧情轮原文压成纯文本背景：剥离思维链/尾部元数据，再剥掉所有标签（<gal>/<z>/<status> 等），
 * 仅保留可读正文，避免把剧情输出格式泄漏到手机生成上下文。
 */
function toPlainStoryText(text: string): string {
  return stripWuwaBoilerplate(text)
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * 构建直连生成的上下文：剧情记忆总结 + 近期剧情背景（纯文本）+ 手机消息历史。
 * 生成时以 max_chat_history: 0 注入，避免读取酒馆楼层。
 *
 * 注意：剧情轮原文含 <gal>/<status>/<UpdateVariable>/思维链，不能直接作为对话历史注入，
 * 否则会把剧情输出格式泄漏进手机回复，导致回复被渲染成玩家消息样式。
 */
export function buildPhoneGeneratePrompts(): PhoneGeneratePrompt[] {
  const prompts: PhoneGeneratePrompt[] = [];

  prompts.push({ role: 'system', content: PHONE_SYSTEM_GUARD });

  const archive = readArchive();
  if (archive.summary.trim()) {
    prompts.push({ role: 'system', content: `【剧情记忆总结】\n${archive.summary.trim()}` });
  }

  const recent = archive.turns.slice(-8);
  if (recent.length) {
    const narrative = recent
      .map((turn) => {
        const label = turn.role === 'user' ? '玩家' : '角色';
        const body = turn.role === 'user' && turn.user_input?.trim()
          ? turn.user_input.trim()
          : toPlainStoryText(turn.text);
        return `${label}：${body}`;
      })
      .join('\n\n')
      .trim();
    if (narrative) {
      prompts.push({
        role: 'system',
        content: `【近期剧情背景（仅供语气/设定参考，禁止续写、扩写或输出任何剧情标签）】\n${narrative}`,
      });
    }
  }

  for (const message of readPhoneChat().slice(-40)) {
    prompts.push({ role: message.is_user ? 'user' : 'assistant', content: message.mes });
  }

  return prompts;
}