import { readArchive } from '../../shared/wuwaArchive';
import { parseWuwaMessage, type WuwaInnerSegment } from './wuwaParser';

export type WuwaAiPage = { kind: 'ai'; message_id: number; segments: WuwaInnerSegment[] };
export type WuwaUserPage = { kind: 'user'; message_id: number; content: string };
export type WuwaPage = WuwaAiPage | WuwaUserPage;

/** 书页最多保留 20 页，超出时丢弃最旧一页并整体前移（滑动窗口） */
export const WUWA_MAX_PAGES = 20;

/** 用户轮正文可能包含 <status>…</status> 系统引导词，展示为书页时剥离 */
function cleanUserText(message: string): string {
  return message.replace(/<status>[\s\S]*?<\/status>/gi, '').trim();
}

/**
 * 从存档 turns 重建书页（不再读聊天楼层）。
 * turns 首轮是开场 assistant（仅展示 AI 剧情页），其后为 用户页+AI页 交替。
 */
export function buildWuwaPagesFromArchive(): WuwaPage[] {
  const turns = readArchive().turns;
  const pages: WuwaPage[] = [];

  for (const turn of turns) {
    if (turn.role === 'assistant') {
      const segments = parseWuwaMessage(turn.text).gal?.segments ?? [];
      if (segments.length) {
        pages.push({ kind: 'ai', message_id: turn.id, segments });
      }
      continue;
    }

    const content = turn.user_input ?? cleanUserText(turn.text);
    if (content) {
      pages.push({ kind: 'user', message_id: turn.id, content });
    }
  }

  return pages.length > WUWA_MAX_PAGES ? pages.slice(pages.length - WUWA_MAX_PAGES) : pages;
}

/** 最新 AI 页的索引（新回合完成后应翻到该页） */
export function lastAiPageIndex(pages: WuwaPage[]): number {
  for (let i = pages.length - 1; i >= 0; i -= 1) {
    if (pages[i].kind === 'ai') return i;
  }
  return 0;
}