import {
  buildWuwaMvuUserPrompt,
} from '../../shared/mvuGeneratePrompt';

import { syncWorldbookBeforeGenerate } from '../../shared/worldbookControl/worldbookPreGenerateSync';

import {
  ensureCompleteWuwaReply,
  finalizeWuwaData,
  normalizeGenerateResult,
  requestWuwaGenerate,
  type WuwaSendOptions,
} from '../../shared/wuwaGenerate';

import { ensureMvuReady, formatWuwaError, getTavernHelper } from '../../shared/wuwaTavern';

import {
  archiveContextPrompts,
  baselineStatBefore,
  readArchive,
  syncArchiveStatToFloorZero,
  updateArchive,
} from '../../shared/wuwaArchive';

import { hasGalBlock } from './wuwaParser';

export { normalizeGenerateResult };
export type { WuwaSendOptions };

/** 当前最新 MVU 基线（stat_data 快照来自聊天变量存档，而非楼层变量） */
export function resolveGameplayMvuBaseline(): Mvu.MvuData {
  const archive = readArchive();
  return { stat_data: { ...archive.stat_data }, initialized_lorebooks: {} };
}

function findTurnIndex(archive_turns: Array<{ id: number; role: string }>, id: number): number {
  for (let i = archive_turns.length - 1; i >= 0; i -= 1) {
    if (archive_turns[i].id === id) return i;
  }
  return -1;
}

/** 剥离 <status> 引导词，得到玩家纯文本输入 */
function cleanUserText(message: string): string {
  return message.replace(/<status>[\s\S]*?<\/status>/gi, '').trim();
}

/** 最后一条 assistant 轮（含其前置 user 轮纯文本），供「重新生成」与 can_regenerate 使用 */
export function getLastRegenerableExchange(): { assistant_id: number; user_input: string } | null {
  const archive = readArchive();
  const turns = archive.turns;
  for (let i = turns.length - 1; i >= 0; i -= 1) {
    const assistant = turns[i];
    if (assistant.role !== 'assistant') continue;
    if (!hasGalBlock(assistant.text)) continue;

    let user_input = '';
    for (let j = i - 1; j >= 0; j -= 1) {
      if (turns[j].role === 'user') {
        user_input = turns[j].user_input ?? cleanUserText(turns[j].text);
        break;
      }
    }
    if (!user_input) return null;

    return { assistant_id: assistant.id, user_input };
  }
  return null;
}

/** 定位一个可重新生成的用户回合（该用户轮 + 其后第一个 assistant） */
function findRegenerableExchangeByUser(user_turn_id: number): {
  user_index: number;
  assistant_index: number;
  user_input: string;
} | null {
  const archive = readArchive();
  const turns = archive.turns;
  const user_index = findTurnIndex(turns, user_turn_id);
  if (user_index < 0 || turns[user_index].role !== 'user') return null;

  const user_input = turns[user_index].user_input ?? cleanUserText(turns[user_index].text);
  if (!user_input) return null;

  let assistant_index = -1;
  for (let j = user_index + 1; j < turns.length; j += 1) {
    if (turns[j].role === 'assistant') {
      assistant_index = j;
      break;
    }
  }

  return { user_index, assistant_index, user_input };
}

export async function sendWuwaMessage(text: string, options: WuwaSendOptions = {}): Promise<string> {
  const input = text.trim();
  if (!input) throw new Error('发送内容为空');

  const TH = getTavernHelper();
  const MvuApi = await ensureMvuReady();
  const archive = readArchive();
  const old_data: Mvu.MvuData = { stat_data: { ...archive.stat_data }, initialized_lorebooks: {} };
  const user_prompt = buildWuwaMvuUserPrompt(input, old_data.stat_data);

  try {
    await syncWorldbookBeforeGenerate(input);

    // 历史上下文在追加本轮 user 之前计算，避免把当前用户输入同时作为 chat_history 与 user_input 重复注入
    const history_prompts = archiveContextPrompts(archive);

    // 追加 user 轮（text 存含 <status> 的完整提示词供上下文注入；user_input 存原始输入供前端展示/编辑回溯）
    updateArchive((a) => {
      a.turns = [...a.turns, { id: a.next_id, role: 'user', text: user_prompt, user_input: input }];
      a.next_id += 1;
      return a;
    });

    let message = await requestWuwaGenerate(TH, user_prompt, { should_stream: true, on_stream: options.on_stream, prompts: history_prompts });
    message = await ensureCompleteWuwaReply(TH, message, old_data.stat_data);
    if (!message.trim()) throw new Error('AI 未返回有效回复');

    const data = await finalizeWuwaData(MvuApi, message, old_data);

    updateArchive((a) => {
      a.turns = [...a.turns, { id: a.next_id, role: 'assistant', text: message, stat_after: data.stat_data }];
      a.next_id += 1;
      a.stat_data = data.stat_data;
      a.game_started = true;
      return a;
    });

    await syncArchiveStatToFloorZero(data.stat_data);

    return message;
  } catch (error) {
    console.error('[鸣潮伪同层] sendWuwaMessage 失败', error);
    throw new Error(formatWuwaError(error));
  }
}

export async function regenerateLastWuwaMessage(options: WuwaSendOptions = {}): Promise<string> {
  const exchange = getLastRegenerableExchange();
  if (!exchange) throw new Error('暂无可重新生成的 AI 回复');

  const TH = getTavernHelper();
  const MvuApi = await ensureMvuReady();
  const archive = readArchive();
  const assistant_index = findTurnIndex(archive.turns, exchange.assistant_id);
  if (assistant_index < 0) throw new Error('定位 AI 回复失败');

  // 重新生成仅注入该 user 轮之前的历史，剔除待重生成的旧 assistant 回复本身
  let user_index = -1;
  for (let j = assistant_index - 1; j >= 0; j -= 1) {
    if (archive.turns[j].role === 'user') {
      user_index = j;
      break;
    }
  }
  const history_prompts = archiveContextPrompts({
    ...archive,
    turns: user_index >= 0 ? archive.turns.slice(0, user_index) : [],
  });

  const baseline = baselineStatBefore(archive, assistant_index);
  const old_data: Mvu.MvuData = { stat_data: { ...baseline }, initialized_lorebooks: {} };

  try {
    const plainInput = exchange.user_input.replace(/<status>[\s\S]*?<\/status>/i, '').trim();
    const hasStatus = /<status>/i.test(exchange.user_input);
    const generate_input = hasStatus
      ? exchange.user_input
      : buildWuwaMvuUserPrompt(plainInput || exchange.user_input, baseline);
    await syncWorldbookBeforeGenerate(plainInput || exchange.user_input);

    let message = await requestWuwaGenerate(TH, generate_input, { should_stream: true, on_stream: options.on_stream, prompts: history_prompts });
    message = await ensureCompleteWuwaReply(TH, message, baseline);
    if (!message.trim()) throw new Error('AI 未返回有效回复');

    const data = await finalizeWuwaData(MvuApi, message, old_data);

    updateArchive((a) => {
      const turns = [...a.turns];
      turns[assistant_index] = { ...turns[assistant_index], text: message, stat_after: data.stat_data };
      a.turns = turns;
      a.stat_data = data.stat_data;
      a.game_started = true;
      return a;
    });

    await syncArchiveStatToFloorZero(data.stat_data);

    return message;
  } catch (error) {
    console.error('[鸣潮伪同层] regenerateLastWuwaMessage 失败', error);
    throw new Error(formatWuwaError(error));
  }
}

/** 编辑指定用户轮并重新生成：删除该轮及其后所有内容，基于其之前状态重建变量基线 */
export async function regenerateWuwaMessageFromUser(
  user_turn_id: number,
  new_text: string,
  options: WuwaSendOptions = {},
): Promise<string> {
  const input = new_text.trim();
  if (!input) throw new Error('编辑内容为空');

  const TH = getTavernHelper();
  const MvuApi = await ensureMvuReady();

  const exchange = findRegenerableExchangeByUser(user_turn_id);
  if (!exchange) throw new Error(`找不到可编辑的用户消息（turn ${user_turn_id}）`);

  const archive = readArchive();
  const baseline = exchange.assistant_index >= 0
    ? baselineStatBefore(archive, exchange.assistant_index)
    : { ...archive.stat_data };
  const old_data: Mvu.MvuData = { stat_data: { ...baseline }, initialized_lorebooks: {} };

  try {
    // 删除该用户轮及其后所有内容
    const kept = archive.turns.slice(0, exchange.user_index);
    const history_prompts = archiveContextPrompts({ ...archive, turns: kept });
    const plainInput = input.replace(/<status>[\s\S]*?<\/status>/i, '').trim();
    const generate_input = buildWuwaMvuUserPrompt(plainInput || input, baseline);

    updateArchive((a) => {
      a.turns = [...kept, { id: a.next_id, role: 'user', text: generate_input, user_input: plainInput || input }];
      a.next_id += 1;
      return a;
    });

    await syncWorldbookBeforeGenerate(plainInput || input);

    let message = await requestWuwaGenerate(TH, generate_input, { should_stream: true, on_stream: options.on_stream, prompts: history_prompts });
    message = await ensureCompleteWuwaReply(TH, message, baseline);
    if (!message.trim()) throw new Error('AI 未返回有效回复');

    const data = await finalizeWuwaData(MvuApi, message, old_data);

    updateArchive((a) => {
      a.turns = [...a.turns, { id: a.next_id, role: 'assistant', text: message, stat_after: data.stat_data }];
      a.next_id += 1;
      a.stat_data = data.stat_data;
      a.game_started = true;
      return a;
    });

    await syncArchiveStatToFloorZero(data.stat_data);

    return message;
  } catch (error) {
    console.error('[鸣潮伪同层] regenerateWuwaMessageFromUser 失败', error);
    throw new Error(formatWuwaError(error));
  }
}