  height: 34px;\n\n  padding: 0 10px;\n\n  cursor: pointer;\n\n  font-weight: 600;\n\n  font-size: calc(14px * var(--hub-font-scale, 1));\n\n\n\n  &--active {\n\n    background: #0369a1;\n\n    color: #fff;\n\n    border-color: #0369a1;\n\n  }\n\n}\n\n\n\n.game-hub__scroll {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 0 6px;\n  position: relative;\n  z-index: 1;\n  font-size: calc(14px * var(--hub-font-scale, 1));\n}\n\n\n\n.game-hub__empty {\n\n  padding: 16px;\n\n  border-radius: 12px;\n\n  background: rgba(248, 250, 252, 0.92);\n\n  border: 1px dashed #cbd5e1;\n\n  color: #64748b;\n\n  line-height: 1.5;\n\n}\n\n\n.game-hub__page {\n  width: 100%;\n}\n\n\n.game-hub__pager {\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n  padding: 6px 0 2px;\n  pointer-events: auto;\n  z-index: 12;\n}\n\n\n.game-hub__pager-btn {\n  min-width: 38px;\n  height: 32px;\n  padding: 0 10px;\n  border: 1px solid #bae6fd;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.85);\n  color: #0369a1;\n  font-size: 20px;\n  line-height: 1;\n  cursor: pointer;\n  transition:\n    background 0.15s ease,\n    opacity 0.15s ease;\n\n  &:hover:not(:disabled) {\n    background: #bae6fd;\n  }\n\n  &:disabled {\n    opacity: 0.4;\n    cursor: not-allowed;\n  }\n}\n\n\n.game-hub__pager-info {\n  font-size: calc(13px * var(--hub-font-scale, 1));\n  font-weight: 700;\n  color: #0369a1;\n  min-width: 64px;\n  text-align: center;\n  letter-spacing: 0.04em;\n}\n\n\n.page-enter-active,\n.page-leave-active {\n  transition:\n    opacity 0.2s ease,\n    transform 0.2s ease;\n}\n\n.page-enter-from {\n  opacity: 0;\n  transform: translateX(16px);\n}\n\n.page-leave-to {\n  opacity: 0;\n  transform: translateX(-16px);\n}\n\n"],"sourceRoot":""}]);
