import { ensureHeroinesAfterCardLogic } from './heroineGuard';
import { applyHeroinesViaMvu } from './mvuPatch';
import {
  buildWuwaMvuContinuationPrompt,
  isWuwaReplyMissingUpdateVariable,
  mergeTruncatedWuwaReply,
} from './mvuGeneratePrompt';
import { collectHeroineNames } from './statDataCompat';
import { preserveHeroinesAfterParse } from './statDataMerge';
import { archiveContextPrompts, readArchive, updateArchive } from './wuwaArchive';
import { stripWuwaBoilerplate } from './wuwaMessageSanitize';
import { getTavernHelper } from './wuwaTavern';

export function normalizeGenerateResult(result: string | GenerateToolCallResult): string {
  return typeof result === 'string' ? result : (result.content ?? '');
}

let generation_seq = 0;
function makeGenerationId(): string {
  generation_seq += 1;
  return `wuwa-${Date.now().toString(36)}-${generation_seq.toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

export type WuwaPrompt = { role: 'system' | 'assistant' | 'user'; content: string };

export interface WuwaSendOptions {
  /** 流式传输时，每次收到完整文本时回调（含最终文本） */
  on_stream?: (full_text: string) => void;
}

export interface WuwaGenerateOptions extends WuwaSendOptions {
  should_stream?: boolean;
  /** 覆盖聊天历史提示词；缺省使用 archive 的上下文 */
  prompts?: WuwaPrompt[];
}

/**
 * 直连酒馆 API 生成（复用酒馆预设中的破限与世界书），不写入任何聊天楼层。
 * 聊天历史由 archive 上下文注入（max_chat_history: 0），确保剧情消息不落楼层。
 */
export async function requestWuwaGenerate(
  TH: typeof TavernHelper,
  user_prompt: string,
  options: WuwaGenerateOptions = {},
): Promise<string> {
  const { should_stream = false, on_stream, prompts } = options;
  const generation_id = should_stream ? makeGenerationId() : undefined;

  const stop_stream = should_stream
    ? eventOn(iframe_events.STREAM_TOKEN_RECEIVED_FULLY, (full_text, gid) => {
        if (gid === generation_id) on_stream?.(full_text);
      }).stop
    : null;

  try {
    const raw = await TH.generate({
      user_input: user_prompt,
      max_chat_history: 0,
      overrides: {
        chat_history: {
          prompts: prompts ?? archiveContextPrompts(readArchive()),
        },
      },
      should_silence: true,
      should_stream,
      generation_id,
    });
    return normalizeGenerateResult(raw);
  } finally {
    stop_stream?.();
  }
}

/** 检测到 gal 后缺少 UpdateVariable 时，续写缺失的 MVU 块 */
export async function ensureCompleteWuwaReply(
  TH: typeof TavernHelper,
  message: string,
  stat_data?: Record<string, unknown>,
): Promise<string> {
  if (!isWuwaReplyMissingUpdateVariable(message)) return message;

  console.warn('[鸣潮伪同层] 回复缺少 UpdateVariable，尝试续写 MVU 块');
  const tail = await requestWuwaGenerate(TH, buildWuwaMvuContinuationPrompt(stat_data));
  if (!tail.trim() || !/<UpdateVariable>/i.test(tail)) {
    console.warn('[鸣潮伪同层] 续写仍未包含 UpdateVariable');
    return message;
  }

  return mergeTruncatedWuwaReply(message, tail);
}

/** 解析 MVU + 修正女性角色 + 对抗 WuWa Logic 清空，返回最终 stat_data */
export async function finalizeWuwaData(
  MvuApi: typeof Mvu,
  message: string,
  old_data: Mvu.MvuData,
): Promise<Mvu.MvuData> {
  let data: Mvu.MvuData;
  try {
    data = preserveHeroinesAfterParse(await MvuApi.parseMessage(message, old_data), old_data);
  } catch (error) {
    console.error('[鸣潮伪同层] MVU 解析失败，仍保存 AI 回复', error);
    data = preserveHeroinesAfterParse(old_data, old_data);
  }

  const heroine_names = collectHeroineNames(old_data.stat_data, data.stat_data);
  try {
    data = await applyHeroinesViaMvu(data, heroine_names);
  } catch (error) {
    console.warn('[鸣潮伪同层] MVU insert 女性角色失败', error);
  }

  ensureHeroinesAfterCardLogic(data, old_data, message);

  return data;
}

/** 生成/刷新记忆总结（静默、不落楼层），写入 archive.summary 并返回总结文本 */
export async function generateArchiveSummary(): Promise<string> {
  const archive = readArchive();
  if (archive.turns.length < 10) return archive.summary;

  const recent = archive.turns
    .slice(-20)
    .map((turn) => `${turn.role === 'user' ? '玩家' : 'AI'}：${stripWuwaBoilerplate(turn.text)}`)
    .join('\n\n');

  const prompt = `<status>[系统指令：剧情总结]\n请用中文把下列剧情对话压缩为 200~400 字要点总结（保留关键人物、地点、事件、好感变化、未完成目标、最新状态）。只输出总结正文，不要任何标签。\n\n${recent}\n</status>`;

  const TH = getTavernHelper();
  const summary = (await requestWuwaGenerate(TH, prompt, { prompts: [] })).trim();
  if (summary) {
    updateArchive((a) => {
      a.summary = summary;
      return a;
    });
  }
  return summary;
}