import { formatWuwaError, notifyWuwaError } from '../../shared/wuwaTavern';
import { getLastRegenerableExchange, regenerateLastWuwaMessage, regenerateWuwaMessageFromUser, sendWuwaMessage, } from './gameFlow';
import { parseWuwaMessage, parseWuwaMessageStreaming } from './wuwaParser';
import { getLatestWuwaMessage, useMessageScope } from './messageScope';
import { buildWuwaPagesFromArchive, lastAiPageIndex } from './wuwaPages';
export const useGameStore = defineStore('wuwa_game', () => {
    const { message_text, is_streaming, message_id } = useMessageScope();
    const user_input = ref('');
    const sending = ref(false);
    const hub_message = ref('');
    /** 最近一次通过伪同层输入栏发送的用户消息，用于在剧情末尾注入用户气泡 */
    const pending_user_message = ref(null);
    /** 用户消息是否已被 AI 消费过一次（AI 已回复），消费后的气泡移到段列表顶部而非末尾 */
    const user_message_consumed = ref(false);
    // —— 剧情书页（翻页功能） ——
    const pages = ref([]);
    const current_page_index = ref(0);
    /** 直连 API 流式生成中的 AI 回复正文（实时更新） */
    const streaming_text = ref('');
    /** 用户刚发送、AI 尚未回复时的临时用户页（streaming 期间展示在末尾） */
    const pending_page = computed(() => {
        if (user_message_consumed.value)
            return null;
        const text = pending_user_message.value?.trim();
        if (!text)
            return null;
        return { kind: 'user', message_id: -1, content: text };
    });
    /** 流式生成中的 AI 回复书页（仅在有可渲染的 gal 内容时展示） */
    const streaming_ai_page = computed(() => {
        if (user_message_consumed.value)
            return null;
        const text = streaming_text.value?.trim();
        if (!text)
            return null;
        const segments = parseWuwaMessageStreaming(text).gal?.segments ?? [];
        if (!segments.length)
            return null;
        return { kind: 'ai', message_id: -1, segments };
    });
    const display_pages = computed(() => {
        const base = pages.value;
        const extra = [];
        const pending = pending_page.value;
        if (pending)
            extra.push(pending);
        if (streaming_ai_page.value)
            extra.push(streaming_ai_page.value);
        if (!extra.length)
            return base;
        return [...base, ...extra];
    });
    const current_page = computed(() => display_pages.value[current_page_index.value] ?? null);
    const page_count = computed(() => display_pages.value.length);
    const can_prev_page = computed(() => current_page_index.value > 0);
    const can_next_page = computed(() => current_page_index.value < display_pages.value.length - 1);
    const parsed = computed(() => {
        const result = parseWuwaMessage(streaming_text.value || hub_message.value || message_text.value);
        if (pending_user_message.value && result.gal) {
            const userSeg = { type: 'user', content: pending_user_message.value };
            const gal = {
                ...result.gal,
                // 未消费时挂末尾（用户刚发送），消费后挂顶部（AI 已回复）
                segments: user_message_consumed.value
                    ? [userSeg, ...result.gal.segments]
                    : [...result.gal.segments, userSeg],
            };
            return { ...result, gal };
        }
        return result;
    });
    const can_regenerate = computed(() => {
        try {
            return Boolean(getLastRegenerableExchange());
        }
        catch {
            return false;
        }
    });
    function refreshMessage() {
        try {
            const latest = getLatestWuwaMessage();
            if (latest)
                hub_message.value = latest.message;
            else if (message_text.value)
                hub_message.value = message_text.value;
        }
        catch (error) {
            console.warn('[鸣潮伪同层] refreshMessage 失败', error);
        }
    }
    /** 开启新聊天后清空本地展示状态，避免旧剧情书页/输入残留到新一局 */
    function resetGame() {
        pages.value = [];
        pages_signature = '';
        current_page_index.value = 0;
        user_input.value = '';
        sending.value = false;
        hub_message.value = '';
        pending_user_message.value = null;
        user_message_consumed.value = false;
        streaming_text.value = '';
    }
    let pages_signature = '';
    function pagesSignature(pages) {
        return pages.map((page) => `${page.kind}:${page.message_id}`).join('|');
    }
    /** 从存档重建书页；结构变化才重置翻页位置，内容变化时原位刷新，避免覆盖用户手动翻页 */
    function refreshPages() {
        const next = buildWuwaPagesFromArchive();
        const sig = pagesSignature(next);
        const structure_changed = sig !== pages_signature;
        pages_signature = sig;
        pages.value = next;
        if (structure_changed) {
            current_page_index.value = pending_page.value
                ? display_pages.value.length - 1
                : lastAiPageIndex(next);
        }
        else if (current_page_index.value >= display_pages.value.length) {
            current_page_index.value = Math.max(0, display_pages.value.length - 1);
        }
    }
    function gotoPage(index) {
        if (!display_pages.value.length)
            return;
        current_page_index.value = Math.max(0, Math.min(index, display_pages.value.length - 1));
    }
    function nextPage() {
        gotoPage(current_page_index.value + 1);
    }
    function prevPage() {
        gotoPage(current_page_index.value - 1);
    }
    /** 流式 token 回调：实时刷新 AI 回复书页并翻到最新页 */
    function onStreamToken(full_text) {
        streaming_text.value = full_text;
        current_page_index.value = Math.max(0, display_pages.value.length - 1);
    }
    /** 直连酒馆 API 生成（含流式），复用酒馆预设中的破限与世界书 */
    async function submitInput(text) {
        const input = (text ?? user_input.value).trim();
        if (!input || sending.value)
            return;
        sending.value = true;
        pending_user_message.value = input;
        user_message_consumed.value = false;
        streaming_text.value = '';
        user_input.value = '';
        // 翻到刚发送的用户书页
        current_page_index.value = Math.max(0, display_pages.value.length - 1);
        try {
            await sendWuwaMessage(input, { on_stream: onStreamToken });
            user_message_consumed.value = true;
            pending_user_message.value = null;
            streaming_text.value = '';
            refreshMessage();
            refreshPages();
        }
        catch (error) {
            console.error('[鸣潮伪同层] 直连 API 发送失败', error);
            notifyWuwaError(formatWuwaError(error));
        }
        finally {
            sending.value = false;
        }
    }
    /** 重新生成最后一条 AI 回复：走保留历史变量的自定义流程，避免变量回退/删除 */
    async function regenerateLastReply() {
        if (!can_regenerate.value || sending.value)
            return;
        sending.value = true;
        streaming_text.value = '';
        user_message_consumed.value = false;
        try {
            await regenerateLastWuwaMessage({ on_stream: onStreamToken });
            user_message_consumed.value = true;
            pending_user_message.value = null;
            streaming_text.value = '';
            refreshMessage();
            refreshPages();
        }
        catch (error) {
            console.error('[鸣潮伪同层] 重新生成失败', error);
            notifyWuwaError(formatWuwaError(error));
        }
        finally {
            sending.value = false;
        }
    }
    /** 编辑用户气泡后：按 message_id 定位该用户消息，改写正文并重新生成其后内容 */
    async function editBubbleAndRegenerate(user_message_id, text) {
        const input = text.trim();
        if (!input || sending.value)
            return;
        sending.value = true;
        try {
            // pending 临时页（message_id < 0）：AI 尚未回复，仅更新待发送文本
            if (user_message_id < 0) {
                pending_user_message.value = input;
                user_message_consumed.value = false;
                refreshPages();
                return;
            }
            // 历史/最新用户页：编辑该用户消息，删除其后所有内容，重新生成
            streaming_text.value = '';
            user_message_consumed.value = false;
            await regenerateWuwaMessageFromUser(user_message_id, input, { on_stream: onStreamToken });
            user_message_consumed.value = true;
            pending_user_message.value = null;
            streaming_text.value = '';
            refreshMessage();
            refreshPages();
        }
        catch (error) {
            console.error('[鸣潮伪同层] 编辑并重新生成失败', error);
            notifyWuwaError(formatWuwaError(error));
        }
        finally {
            sending.value = false;
        }
    }
    function applyOption(text) {
        user_input.value = text;
        submitInput(text);
    }
    watch(message_text, () => refreshMessage());
    refreshMessage();
    refreshPages();
    watch(() => parsed.value.gal?.segments, segments => {
        if (!segments?.length)
            return;
        for (const seg of segments) {
            if (seg.type === 'main' && seg.pic) {
                window.unlockCgByRoleAndScene?.(seg.name, seg.pic);
            }
        }
        const raw = hub_message.value || message_text.value;
        if (raw.includes('<gal>'))
            window.unlockCgFromGalContent?.(raw);
    }, { deep: true, immediate: true });
    eventOn(tavern_events.STREAM_TOKEN_RECEIVED, () => refreshMessage());
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, () => {
        // 直连 API 已把 assistant 消息写入聊天：清空流式/待发送临时状态，切到真实 AI 页
        streaming_text.value = '';
        user_message_consumed.value = true;
        pending_user_message.value = null;
        refreshMessage();
        refreshPages();
    });
    // 酒馆生成结束时重置发送状态，将当前用户气泡标记为已消费，并重建书页
    eventOn(tavern_events.GENERATION_ENDED, () => {
        sending.value = false;
        user_message_consumed.value = true;
        refreshPages();
    });
    eventOn(tavern_events.CHAT_CHANGED, () => {
        pages.value = [];
        pages_signature = '';
        current_page_index.value = 0;
        refreshPages();
    });
    /** 统一刷新剧情正文与书页（供外层 shell 在 game_started 翻转后同步 store 状态） */
    function refresh() {
        refreshMessage();
        refreshPages();
    }
    return {
        user_input,
        sending,
        parsed,
        can_regenerate,
        is_streaming,
        message_id,
        pending_user_message,
        user_message_consumed,
        current_page,
        current_page_index,
        page_count,
        can_prev_page,
        can_next_page,
        gotoPage,
        nextPage,
        prevPage,
        submitInput,
        regenerateLastReply,
        applyOption,
        editBubbleAndRegenerate,
        refreshMessage,
        refresh,
        resetGame,
    };
});
